/* using a predicate function sel() to select elements */
int* grep(int *in, int len, int *outlen, int (*sel)(int), int inplace)
{
    int i, j, *out;

    if (inplace)    out = in;
    else        out = malloc(sizeof(int) * len);

    for (i = j = 0; i < len; i++)
        if (sel(in[i]))
            out[j++] = in[i];

    if (!inplace && j < len)
        out = realloc(out, sizeof(int) * j);

    *outlen = j;
    return out;
}

